fn is_decimal_with_two_precision(s: &[u8]) -> bool {
    // We need at least 3 characters: one '.' and two trailing characters.
    if s.len() < 3 {
        return false;
    }
    // Check if the character at position len - 3 is a dot.
    s[s.len() - 3] == b'.'
}

